import json
from pathlib import Path
P=Path(__file__).resolve().parent
def shot(id,source,frame,gen,target,camera,key,motion):
 return dict(id=id,source_shot=source,source_frame=frame,generate_frames=gen,target_frames=target,camera=camera,key_prompt=key,motion_prompt=motion)
def write(group,rows):
 for r in rows:r['group']=group
 (P/f'group-{group:02}.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf8')
